<?php
/** Free and Pro feature comparison page. */
namespace CHADA_AIO;
defined('ABSPATH') || exit;

/** @var list<array{label: string, features: list<array{name: string, description: string, free: bool, pro: bool}>}> $chada_aio_groups Feature groups. */
/** @var bool $chada_aio_pro_available Whether the compatible Pro add-on is ready. */
assert(isset($chada_aio_groups));
assert(isset($chada_aio_pro_available));
$chada_aio_column_count = $chada_aio_pro_available ? 3 : 2;
?><p class="description"><?php if ($chada_aio_pro_available): ?><?php esc_html_e('Free provides the complete core workflow. Pro adds clearly marked selective backup, migration, and bulk optimization providers while preserving every Free feature.', 'chada-aio'); ?><?php else: ?><?php esc_html_e('This site is running the Free edition. The list below shows the features included in this installation.', 'chada-aio'); ?><?php endif; ?></p>
<div class="chada-edition-cards<?php echo $chada_aio_pro_available ? '' : ' chada-edition-cards-free'; ?>" data-tour="features"><section class="chada-edition-card chada-free-card"><p class="chada-eyebrow"><?php esc_html_e('Included by default', 'chada-aio'); ?></p><h2><?php esc_html_e('Free', 'chada-aio'); ?></h2><p><?php esc_html_e('Backup All, Migrate All, selected-image optimization, cleanup, recovery, and the Setup Wizard.', 'chada-aio'); ?></p></section><?php if ($chada_aio_pro_available): ?><section class="chada-edition-card chada-pro-card"><p class="chada-eyebrow"><?php esc_html_e('Optional add-on', 'chada-aio'); ?></p><h2><?php esc_html_e('Pro', 'chada-aio'); ?></h2><p><?php esc_html_e('Everything in Free, plus component backup and migration, and Library, Quarter, and Year optimization.', 'chada-aio'); ?></p></section><?php endif; ?></div>
<div class="chada-table-wrap" data-tour="features"><table class="widefat fixed striped chada-features"><caption class="screen-reader-text"><?php echo esc_html($chada_aio_pro_available ? __('Chada AIO Free and Pro feature comparison', 'chada-aio') : __('Chada AIO Free feature list', 'chada-aio')); ?></caption><thead><tr><th scope="col"><?php esc_html_e('Feature', 'chada-aio'); ?></th><th scope="col"><?php esc_html_e('Free', 'chada-aio'); ?></th><?php if ($chada_aio_pro_available): ?><th scope="col"><?php esc_html_e('Pro', 'chada-aio'); ?></th><?php endif; ?></tr></thead><tbody><?php foreach ($chada_aio_groups as $chada_aio_group): ?><tr class="chada-section"><th colspan="<?php echo esc_attr((string) $chada_aio_column_count); ?>" scope="rowgroup"><?php echo esc_html($chada_aio_group['label']); ?></th></tr><?php foreach ($chada_aio_group['features'] as $chada_aio_feature): ?><tr><th scope="row"><span><?php echo esc_html($chada_aio_feature['name']); ?></span><span class="description"><?php echo esc_html($chada_aio_feature['description']); ?></span></th><?php $chada_aio_availability = [$chada_aio_feature['free']]; if ($chada_aio_pro_available) { $chada_aio_availability[] = $chada_aio_feature['pro']; } foreach ($chada_aio_availability as $chada_aio_feature_available): ?><td><span class="chada-availability <?php echo $chada_aio_feature_available ? 'yes' : 'no'; ?>" aria-label="<?php echo esc_attr($chada_aio_feature_available ? __('Available', 'chada-aio') : __('Not included', 'chada-aio')); ?>"><span aria-hidden="true"><?php echo $chada_aio_feature_available ? '✓' : '×'; ?></span><span class="screen-reader-text"><?php echo esc_html($chada_aio_feature_available ? __('Available', 'chada-aio') : __('Not included', 'chada-aio')); ?></span></span></td><?php endforeach; ?></tr><?php endforeach; ?><?php endforeach; ?></tbody></table></div>
